mod config;
mod error;
mod sleeper;

pub use config::RetryConfig;
pub use error::RetryError;
pub use sleeper::{FakeSleeper, Sleeper};

/// Runs `job` until it succeeds or the retry budget is exhausted.
/// The public signature is frozen; do not change it.
pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    // A zero budget is invalid according to RetryConfig's contract. Treat it
    // defensively as one attempt rather than silently skipping the job.
    let max_attempts = config.max_attempts.max(1);
    let mut attempt = 1;
    let mut delay_ms = config.base_delay_ms.min(config.max_delay_ms);

    loop {
        match job() {
            Ok(()) => return Ok(()),
            Err(error) if error.is_transient() && attempt < max_attempts => {
                sleeper.sleep_ms(delay_ms);
                attempt += 1;
                delay_ms = delay_ms.saturating_mul(2).min(config.max_delay_ms);
            }
            Err(error) => return Err(error),
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn retries_transient_errors_with_bounded_exponential_delays() {
        let config = RetryConfig {
            max_attempts: 5,
            base_delay_ms: 10,
            max_delay_ms: 25,
        };
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;

        let result = run_job(&config, &mut sleeper, || {
            calls += 1;
            if calls < 5 {
                Err(RetryError::Transient("try again".into()))
            } else {
                Ok(())
            }
        });

        assert_eq!(result, Ok(()));
        assert_eq!(calls, 5);
        assert_eq!(sleeper.sleeps, vec![10, 20, 25, 25]);
    }

    #[test]
    fn permanent_errors_return_without_retrying() {
        let config = RetryConfig {
            max_attempts: 4,
            base_delay_ms: 10,
            max_delay_ms: 100,
        };
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;

        let result = run_job(&config, &mut sleeper, || {
            calls += 1;
            Err(RetryError::Permanent("invalid input".into()))
        });

        assert_eq!(result, Err(RetryError::Permanent("invalid input".into())));
        assert_eq!(calls, 1);
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn attempt_limit_includes_first_call() {
        let config = RetryConfig {
            max_attempts: 3,
            base_delay_ms: 7,
            max_delay_ms: 100,
        };
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;

        let result = run_job(&config, &mut sleeper, || {
            calls += 1;
            Err(RetryError::Transient("unavailable".into()))
        });

        assert_eq!(result, Err(RetryError::Transient("unavailable".into())));
        assert_eq!(calls, 3);
        assert_eq!(sleeper.sleeps, vec![7, 14]);
    }
}

//! Retry configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Must be >= 1.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Maximum delay between attempts, in milliseconds.
    pub max_delay_ms: u64,
}

# jobrunner

Small job runner with a pluggable retry policy.

## Retry policy

`run_job` accepts a `RetryConfig`, an injected `Sleeper`, and a job closure.
`max_attempts` is the total number of calls, including the first call. Only
`RetryError::Transient` failures are retried; `RetryError::Permanent` failures
are returned immediately.

Retries wait using bounded exponential backoff. The first retry waits
`base_delay_ms`, each subsequent delay doubles, and delays are capped at
`max_delay_ms`. The injected `FakeSleeper` records delays, making the policy
easy to test without waiting.

```rust
use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

let config = RetryConfig {
    max_attempts: 4,
    base_delay_ms: 100,
    max_delay_ms: 1_000,
};
let mut sleeper = FakeSleeper::default();
let result = run_job(&config, &mut sleeper, || {
    // perform work here
    Ok::<(), RetryError>(())
});
assert!(result.is_ok());
```

use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

#[test]
fn transient_failure_then_success_uses_expected_backoff() {
    let config = RetryConfig {
        max_attempts: 4,
        base_delay_ms: 5,
        max_delay_ms: 9,
    };
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        match calls {
            1 | 2 => Err(RetryError::Transient("temporary outage".into())),
            _ => Ok(()),
        }
    });

    assert_eq!(result, Ok(()));
    assert_eq!(calls, 3);
    assert_eq!(sleeper.sleeps, vec![5, 9]);
}

#[test]
fn permanent_failure_is_not_retried() {
    let config = RetryConfig {
        max_attempts: 5,
        base_delay_ms: 1,
        max_delay_ms: 10,
    };
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        Err(RetryError::Permanent("bad request".into()))
    });

    assert_eq!(result, Err(RetryError::Permanent("bad request".into())));
    assert_eq!(calls, 1);
    assert!(sleeper.sleeps.is_empty());
}

