+    max_attempts: 4,
+    base_delay_ms: 100,
+    max_delay_ms: 1_000,
+};
+let mut sleeper = FakeSleeper::default();
+let result = run_job(&config, &mut sleeper, || {
+    // perform work here
+    Ok::<(), RetryError>(())
+});
+assert!(result.is_ok());
+```
